        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var lang = this._lang();

            var nameEl = document.getElementById('roundNameDisplay');
            if (nameEl) nameEl.textContent = lang === 'es' ? round.nameEs : round.nameEn;

            var iconEl = document.getElementById('briefingIcon');
            if (iconEl) iconEl.textContent = round.icon;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                var briefings = lang === 'es' ? this.BRIEFINGS_ES : this.BRIEFINGS_EN;
                briefEl.innerHTML = briefings[idx];
            }

            for (var i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].controls);
                if (panel) panel.style.display = (i === idx) ? 'block' : 'none';
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new PandemiaAdapter(), {
            simulationType: 'pandemia_crisis_513',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

